class Solution {
public:
    vector<string> buildArray(vector<int>& target, int n) {
        vector<string> ops;
        int idx = 0;
        int sz = (int)target.size();
        for (int i = 1; i <= n && idx < sz; i++) {
            if (i == target[idx]) {
                ops.push_back("Push");
                idx++;
            } else {
                ops.push_back("Push");
                ops.push_back("Pop");
            }
        }
        return ops;
    }
};
